-- Synchronize every product currently in src/lib/data.ts by stable slug and catalog id.
START TRANSACTION;
ON DUPLICATE KEY UPDATE
  external_id = VALUES(external_id), category_id = VALUES(category_id),
  name_de = VALUES(name_de), name_fr = VALUES(name_fr), name_en = VALUES(name_en),
  subtitle_de = VALUES(subtitle_de), subtitle_fr = VALUES(subtitle_fr), subtitle_en = VALUES(subtitle_en),
  description_de = VALUES(description_de), description_fr = VALUES(description_fr), description_en = VALUES(description_en),
  name = VALUES(name), description = VALUES(description), price_eur = VALUES(price_eur),
  image_url = VALUES(image_url), gallery = VALUES(gallery), is_hot = VALUES(is_hot), stock = VALUES(stock),
  created_at = VALUES(created_at), is_active = 1;
COMMIT;
